mapper.select:
select ccb.*, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=ccb.bp_id) bp_name, (select hbm.bp_code from hls_bp_master hbm where hbm.bp_id=ccb.bp_id) bp_code, (select hbt.description from hls_bp_type hbt where hbt.bp_type=ccb.bp_type) bp_type_desc from con_contract_bp ccb
1=1
and ccb.contract_id = #{contractId}

select ccb.bp_id, ccb.bp_category, (select bc.description from hls_bp_category bc where bc.bp_category = ccb.bp_category) bp_category_n, hbm.bp_code, hbm.bp_name, ba.bank_account_id, ba.bank_account_name, ba.bank_account_num, nvl(ba.bank_branch_name,ba.bank_full_name) bank_branch_name, ba.bank_full_name from con_contract_bp ccb, hls_bp_master_bank_account ba, hls_bp_master hbm where hbm.BP_ID = ccb.bp_id and ccb.bp_id = ba.BP_ID
and ccb.contract_id = #{contractId}
and ccb.bp_id = #{bpId}
and ccb.bp_category = #{bp_category}

SELECT ba.bp_id,
hbm.bp_category,
(select bc.description from hls_bp_category bc where bc.bp_category = hbm.bp_category) bp_category_n,
hbm.bp_code,
hbm.bp_name,
ba.bank_account_id,
ba.bank_account_name,
ba.bank_account_num,
nvl(ba.bank_branch_name, ba.bank_full_name)                                            bank_branch_name,
ba.bank_full_name
FROM hls_bp_master_bank_account ba,
hls_bp_master hbm
WHERE ba.BP_ID = hbm.bp_id

    and hbm.bp_id = #{bpId}


    and hbm.bp_category = #{bpCategory}


    and ba.bank_account_name = #{bankAccountName}


    and ba.bank_account_num = #{bankAccountNum}


    and ba.bank_full_name = #{bankFullName}


    and ba.bank_branch_name = #{bankBranchName}

SELECT ccb.contract_id, ccb.record_id, ccb.bp_id, hbc.description bp_category_n, ccb.bp_class, ccb.bp_category, (SELECT hbt.description AS value_name FROM hls_business_type hbt WHERE hbt.document_category = 'HLS_BP_MASTER' AND hbt.business_type=hbm.bp_class) bp_class_n, hbm.BP_CODE, hbm.bp_name bp_id_n, hbm.bp_name, hbm.bp_name bp_name_n, hbm.WORKING_PLACE, hbm.POSITION, (select meaning from sys_code_value_b_v where code = 'HLS211_GENDER' and code_value = hbm.GENDER) gender_n, hbm.GENDER, hbm.MARITAL_STATUS, (select meaning from sys_code_value_b_v where code = 'HLS211_MARITAL_STATUS' and code_value = hbm.MARITAL_STATUS) MARITAL_STATUS_N, hbm.AGE, hbm.DATE_OF_BIRTH, hbm.ANNUAL_INCOME, hbm.NUMBER_OF_CHILDREN, hbm.REF_V03, hbm.INDUSTRY, (select DESCRIPTION from hls_stat_class where CLASS_USAGE = 'BIZ_PARTNER' and CLASS_CODE = hbm.INDUSTRY) industry_n, hbm.COMPANY_NATURE, (select meaning from sys_code_value_b_v where code = 'PRJ_NATURE_OF_BUSINESS' and code_value = hbm.COMPANY_NATURE) company_nature_n, hbm.ACTUAL_CONTROLLER, hbm.LEGAL_PERSON, hbm.FOUNDED_DATE, hbm.REGISTERED_CAPITAL, hbm.PAID_UP_CAPITAL, hbm.CREDIT_RATING, hbm.LISTED_COMPANY_FLAG, hbm.ENTERPRISE_SCALE, (select meaning from sys_code_value_b_v where code = 'ENTERPRISE_SCALE_TYPE' and code_value = hbm.ENTERPRISE_SCALE) enterprise_scale_n, hbm.SALE_TYPE, (select meaning from sys_code_value_b_v where code = 'HR_SALE_TYPE' and code_value = hbm.SALE_TYPE) sale_type_n, ccb.bp_role_type bp_role_type, ( SELECT hbt.description FROM hls_bp_type hbt WHERE hbt.bp_type = ccb.bp_role_type AND hbt.bp_category = ccb.bp_category ) bp_role_type_n FROM con_contract_bp ccb, hls_bp_master hbm, hls_bp_category hbc WHERE ccb.bp_id = hbm.BP_ID AND ccb.bp_category = hbc.bp_category
and ccb.contract_id = #{contractId}
and ccb.bp_category = #{bpCategory}
order by ccb.bp_category desc

select ccb.bp_id, ccb.bp_category, (select bc.description from hls_bp_category bc where bc.bp_category = ccb.bp_category) bp_category_n, hbm.bp_code, hbm.bp_name, ba.bank_account_id, ba.bank_account_name, ba.bank_account_num, nvl(ba.bank_branch_name,ba.bank_full_name) bank_branch_name, ba.bank_full_name from con_contract_bp ccb left join hls_bp_master_bank_account ba on ccb.bp_id = ba.BP_ID, hls_bp_master hbm where hbm.BP_ID = ccb.bp_id
and ccb.contract_id = #{contractId}
and ccb.bp_id = #{bpId}
and ccb.bp_category = #{bp_category}
and ccb.bp_name = #{bpName}
and hbm.bp_code = #{bpCode}

select distinct hbm.bp_code, ccb.bp_id, ccb.bp_category, (select bc.description from hls_bp_category bc where bc.bp_category = ccb.bp_category) bp_category_n, hbm.bp_name, ba.bank_account_id, ba.bank_account_name, ba.bank_account_num, ba.bank_branch_name, ba.bank_full_name from con_contract_bp ccb,hls_bp_master_bank_account ba,hls_bp_master hbm where hbm.BP_ID = ccb.bp_id and ccb.bp_id = ba.BP_ID and ccb.bp_category !='GUARANTOR'
and ccb.contract_id = #{contractId}
and ccb.bp_id = #{bpId}
and ccb.bp_category = #{bp_category}
and ccb.bp_name = #{bpName}
and hbm.bp_code = #{bpCode}

select distinct
hbm.BP_ID,
hbm.bp_code,
(select bc.description
from hls_bp_category bc
where bc.bp_category = ccb.bp_category) bp_category_n,
hbm.bp_name
from con_contract_bp ccb,hls_bp_master hbm
where hbm.BP_ID = ccb.bp_id
and ccb.bp_category !='GUARANTOR'

    and ccb.contract_id = #{contractId}


    and ccb.bp_id = #{bpId}


    and ccb.bp_category = #{bp_category}


    and ccb.bp_name = #{bpName}


    and hbm.bp_code = #{bpCode}
